# Build excerpt texts for teacher-forced analysis
import json
rows = [json.loads(l) for l in open('/practice/baseline/original.jsonl')]
cut = [r for r in rows if r['finish']=='length']
cor = [r for r in rows if r['correct'] and r['finish']=='stop']

def excerpt(text, target_len=1400):
    ids = tok.encode(text).ids
    # take from the middle-end region where loops happen
    start = max(0, len(ids) - target_len)
    return tok.decode(ids[start:])

loop_texts, norm_texts = [], []
for r in cut[:3]:
    loop_texts.append(excerpt(r['text']))
for r in cor[:3]:
    norm_texts.append(excerpt(r['text']))
for i,t in enumerate(loop_texts):
    print('loop', i, len(tok.encode(t).ids), 'Waits', t.count('Wait'))
for i,t in enumerate(norm_texts):
    print('norm', i, len(tok.encode(t).ids), 'Waits', t.count('Wait'))
json.dump({'loop':loop_texts,'norm':norm_texts}, open('/work/excerpts.json','w'))

