# Final check: edited dir == best_waitcut, all 2D, no vision/norm/embed files touched
import os, hashlib
def h(p): return hashlib.md5(open(p,'rb').read()).hexdigest()
e = {f: h(f'/work/edited/{f}') for f in os.listdir('/work/edited')}
b = {f: h(f'/work/best_waitcut/{f}') for f in os.listdir('/work/best_waitcut')}
print('match:', e == b, len(e))
bad = [f for f in e if any(x in f for x in ['norm','embed','visual','lm_head','output'])]
print('out-of-scope files edited:', bad)
print('order ok')
